import numpy as np


def heilbronn_convex13() -> np.ndarray:
    """Deterministic soft-min search followed by a signed maximin epigraph polish."""
    n = 13
    rng = np.random.default_rng(42)
    triples = np.array(
        [(i, j, k) for i in range(n) for j in range(i + 1, n)
         for k in range(j + 1, n)], dtype=int
    )

    # Build explicit cyclic-hull topology seeds.  Each seed has m ordered
    # boundary contacts and 13-m staggered interior points.
    topology_seeds = []
    center = np.array([0.5, 0.5], dtype=float)
    interior = np.array([
        [0.37, 0.37], [0.63, 0.37], [0.50, 0.50],
        [0.37, 0.63], [0.63, 0.63], [0.50, 0.31],
        [0.50, 0.69], [0.31, 0.50], [0.69, 0.50],
        [0.43, 0.50], [0.57, 0.50]
    ], dtype=float)
    for m in (7, 8, 9, 10):
        angles = np.linspace(0.0, 2.0 * np.pi, m, endpoint=False)
        for reflected in (False, True):
            phase = 0.17 if reflected else -0.11
            radii = 0.435 + 0.018 * np.cos(3.0 * angles + phase)
            if reflected:
                radii = radii[::-1]
            hull_seed = center + radii[:, None] * np.column_stack(
                (np.cos(angles), np.sin(angles))
            )
            if reflected:
                hull_seed[:, 1] = 1.0 - hull_seed[:, 1]
            # Use a distinct staggered prefix for each topology so that
            # interior crowding is not tied to the incumbent 11-contact seed.
            count = n - m
            inner = interior[:count].copy()
            inner[:, 0] += 0.012 * np.sin(np.arange(count) + m)
            inner[:, 1] += 0.010 * np.cos(1.7 * np.arange(count) + m)
            topology_seeds.append(np.vstack((hull_seed, inner)))
    base = topology_seeds[0].copy()

    try:
        from scipy.optimize import minimize
        from scipy.spatial import ConvexHull
        from scipy.special import logsumexp
    except Exception:
        return base

    def dets(p):
        a, b, c = p[triples[:, 0]], p[triples[:, 1]], p[triples[:, 2]]
        return ((b[:, 0] - a[:, 0]) * (c[:, 1] - a[:, 1])
                - (b[:, 1] - a[:, 1]) * (c[:, 0] - a[:, 0]))

    def score(p):
        try:
            h = ConvexHull(p).volume
        except Exception:
            return 0.0
        return float(0.5 * np.min(np.abs(dets(p))) / h) if h > 1e-12 else 0.0

    def soft_objective(x, temperature):
        p = x.reshape(n, 2)
        try:
            h = ConvexHull(p).volume
        except Exception:
            return 1e4
        if h < 1e-12:
            return 1e4
        ar = 0.5 * np.abs(dets(p)) / h
        return float(temperature * logsumexp(-ar / temperature))

    best = base.copy()
    best_value = score(best)

    # Rank the eight topology/reflection starts cheaply, then continue only
    # with the four most promising cyclic-hull contact patterns.
    ranked = []
    for start in topology_seeds:
        try:
            surrogate = soft_objective(start.ravel(), 0.001)
        except Exception:
            surrogate = 1e4
        ranked.append((surrogate, start))
    ranked.sort(key=lambda item: item[0])
    for _, start in ranked[:4]:
        x = np.asarray(start, dtype=float).copy().ravel()
        for temp in (0.004, 0.002, 0.001, 0.0005, 0.00025,
                     0.00012, 0.00006):
            r = minimize(
                lambda z, t=temp: soft_objective(z, t), x,
                method="L-BFGS-B", bounds=[(0.002, 0.998)] * (2 * n),
                options={"maxiter": 500, "ftol": 1e-13,
                         "gtol": 1e-8, "maxls": 40}
            )
            if np.isfinite(r.fun):
                x = r.x
        candidate = x.reshape(n, 2)
        v = score(candidate)
        if v > best_value:
            best, best_value = candidate.copy(), v

    try:
        from scipy.optimize import linprog

        def local_interior_step(p, idx, signs):
            """Compute an exact LP best response for one fixed interior point."""
            others = np.delete(p, idx, axis=0)
            try:
                oh = ConvexHull(others)
            except Exception:
                return None
            hull_area = float(oh.volume)
            if hull_area <= 1e-12:
                return None

            # The selected point must remain in the convex hull of its
            # thirteen-point neighbors, expressed as linear half-planes.
            q = others[oh.vertices]
            edges = np.roll(q, -1, axis=0) - q
            aub, bub = [], []
            for edge, origin in zip(edges, q):
                # edge_x*(y-y0)-edge_y*(x-x0) >= 0.
                aub.append([edge[1], -edge[0], 0.0])
                bub.append(edge[1] * origin[0] - edge[0] * origin[1])

            current_dets = dets(p)
            for r, (i, j, k) in enumerate(triples):
                if idx not in (i, j, k):
                    aub.append([0.0, 0.0, 1.0])
                    bub.append(0.5 * abs(current_dets[r]) / hull_area)
                    continue

                # Evaluate the determinant at (0,0), (1,0), and (0,1);
                # this avoids index-order sign mistakes in the affine form.
                def det_at(x, y):
                    trial = p[[i, j, k]].copy()
                    trial[(i, j, k).index(idx)] = (x, y)
                    return ((trial[1, 0] - trial[0, 0]) *
                            (trial[2, 1] - trial[0, 1]) -
                            (trial[1, 1] - trial[0, 1]) *
                            (trial[2, 0] - trial[0, 0]))

                const = det_at(0.0, 0.0)
                coef = np.array([det_at(1.0, 0.0) - const,
                                 det_at(0.0, 1.0) - const])
                s = signs[r]
                # -s*area(x)/hull_area + t <= 0.
                aub.append([-0.5 * s * coef[0] / hull_area,
                            -0.5 * s * coef[1] / hull_area, 1.0])
                bub.append(0.5 * s * const / hull_area)

            result = linprog(
                [0.0, 0.0, -1.0], A_ub=np.asarray(aub),
                b_ub=np.asarray(bub),
                bounds=[(0.0001, 0.9999), (0.0001, 0.9999),
                        (0.0, 0.1)],
                method="highs"
            )
            return result.x[:2].copy() if result.success else None

        # Cyclic exact best responses for interior points.  Recompute signs
        # after every accepted move because the active affine contacts change.
        for _ in range(6):
            pass_start = best_value
            try:
                hull_indices = set(ConvexHull(best).vertices.tolist())
            except Exception:
                break

            for idx in range(n):
                if idx in hull_indices:
                    continue
                signs = np.sign(dets(best))
                signs[signs == 0.0] = 1.0
                candidate = local_interior_step(best, idx, signs)
                if candidate is None:
                    continue
                trial = best.copy()
                trial[idx] = candidate
                value = score(trial)
                if value > best_value + 1e-12:
                    best, best_value = trial, value

            # One bounded SLSQP coordinate pass over the current hull,
            # retaining the requested deterministic vertex fallback.
            try:
                hull_indices = ConvexHull(best).vertices
            except Exception:
                break
            for idx in hull_indices:
                anchor = best.copy()

                def vertex_objective(z):
                    trial = anchor.copy()
                    trial[idx] = z
                    return -score(trial)

                result = minimize(
                    vertex_objective, anchor[idx], method="SLSQP",
                    bounds=[(0.0001, 0.9999)] * 2,
                    options={"maxiter": 120, "ftol": 1e-11, "disp": False}
                )
                if np.isfinite(result.fun):
                    trial = anchor.copy()
                    trial[idx] = result.x
                    value = score(trial)
                    if value > best_value + 1e-12:
                        best, best_value = trial, value

            if best_value <= pass_start + 1e-12:
                break
    except Exception:
        pass

    return np.asarray(np.clip(best, 0.0, 1.0), dtype=float)
